#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

readonly DEFAULT_PORT=4096
readonly DEFAULT_UPDATE_HOUR=4
readonly DEFAULT_BASE_IMAGE="debian:trixie-slim"
readonly DEFAULT_APT_PACKAGES="build-essential python3-dev"
readonly HEALTH_TIMEOUT_SECONDS=900
readonly OVERRIDE_FILE="docker-compose.override.yml"

expand_path() {
  local path="$1"
  printf '%s' "${path/#\~/$HOME}"
}

host_timezone() {
  local link
  link=$(readlink /etc/localtime 2>/dev/null || true)
  case "$link" in
    *zoneinfo/*) printf '%s' "${link##*zoneinfo/}" ;;
    *) printf 'UTC' ;;
  esac
}

generate_password() {
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -hex 24
  else
    od -An -N24 -tx1 /dev/urandom | tr -d ' \n'
  fi
}

# Directory to mount so that an absolute symlink target resolves in the container.
# The parent is mounted so that sibling targets (e.g. many skills in one folder)
# collapse into a single mount; the home directory or / itself is never mounted.
mount_dir_for_target() {
  local target="$1" parent
  parent=$(dirname "$target")
  if [[ "$parent" == "/" || "$parent" == "$HOME" || "$parent" == "$(dirname "$HOME")" ]]; then
    printf '%s' "$target"
  else
    printf '%s' "$parent"
  fi
}

# Prints absolute symlink targets found in the given directories, one per line.
absolute_symlink_targets() {
  local dir link target
  for dir in "$@"; do
    [[ -d "$dir" ]] || continue
    while IFS= read -r link; do
      target=$(readlink "$link")
      [[ "$target" == /* ]] || continue
      if [[ ! -e "$target" ]]; then
        warn "ссылка $link ведёт в $target, а такого пути нет и на хосте; пропускаю" >&2
        continue
      fi
      printf '%s\n' "$target"
    done < <(find "$dir" -maxdepth 2 -type l -not -path '*/node_modules/*')
  done
}

# Reads paths from stdin, prints them sorted and without entries nested in others.
drop_nested_paths() {
  local path kept=""
  while IFS= read -r path; do
    [[ -n "$path" ]] || continue
    if [[ -n "$kept" && ( "$path" == "$kept" || "$path" == "$kept"/* ) ]]; then
      continue
    fi
    printf '%s\n' "$path"
    kept="$path"
  done < <(sort -u)
}

copy_to_clipboard() {
  if command -v pbcopy >/dev/null 2>&1; then pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then wl-copy
  elif command -v xclip >/dev/null 2>&1; then xclip -selection clipboard
  else return 1
  fi
}

# Prints ports the opencode config reaches on the loopback (127.0.0.1, localhost,
# [::1]), comma-separated. The container's own server port is excluded.
config_loopback_ports() {
  local dir="$1"
  { grep -ohE '(127\.0\.0\.1|localhost|\[::1\]):[0-9]+' "$dir"/*.json "$dir"/*.jsonc 2>/dev/null || true; } \
    | sed 's/.*://' | sort -un | grep -vx "$DEFAULT_PORT" | paste -sd, - || true
}

wait_until_ready() {
  local url="$1" waited=0 step_seconds=5
  printf '  ждём сервер'
  while (( waited < HEALTH_TIMEOUT_SECONDS )); do
    if curl -fsS -o /dev/null -m 5 "$url" 2>/dev/null; then
      printf ' готово\n'
      return 0
    fi
    printf '.'
    sleep "$step_seconds"
    waited=$((waited + step_seconds))
  done
  printf '\n'
  return 1
}

run_wizard() {

TOTAL_STAGES=9

cd "$(dirname "$0")/.."

banner "opencode в Docker: настройка и запуск"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Проверка окружения"
if ! command -v docker >/dev/null 2>&1; then
  warn "docker не найден. Поставь Docker Desktop или OrbStack и запусти визард снова."
  exit 1
fi
if ! docker compose version >/dev/null 2>&1; then
  warn "нет docker compose v2 (команда docker compose). Обнови Docker и запусти визард снова."
  exit 1
fi
if ! docker info >/dev/null 2>&1; then
  warn "Docker-демон не отвечает. Запусти Docker Desktop или OrbStack и запусти визард снова."
  exit 1
fi
say "✓ $(docker compose version)"

HOST_OPENCODE_CONFIG="$HOME/.config/opencode"
if [[ -d "$HOST_OPENCODE_CONFIG" ]]; then
  say "✓ конфиг opencode: $HOST_OPENCODE_CONFIG"
else
  warn "не нашёл $HOST_OPENCODE_CONFIG"
  while true; do
    ask HOST_OPENCODE_CONFIG "Путь к папке с конфигом opencode:"
    HOST_OPENCODE_CONFIG=$(expand_path "$HOST_OPENCODE_CONFIG")
    [[ -d "$HOST_OPENCODE_CONFIG" ]] && break
    warn "папки $HOST_OPENCODE_CONFIG нет"
  done
  write_env HOST_OPENCODE_CONFIG "$HOST_OPENCODE_CONFIG"
fi

HOST_GITCONFIG="$HOME/.gitconfig"
if [[ -f "$HOST_GITCONFIG" ]]; then
  say "✓ git-конфиг: $HOST_GITCONFIG"
else
  warn "не нашёл $HOST_GITCONFIG. Контейнеру нужен git-конфиг с user.name и user.email."
  while true; do
    ask HOST_GITCONFIG "Путь к git-конфигу:"
    HOST_GITCONFIG=$(expand_path "$HOST_GITCONFIG")
    [[ -f "$HOST_GITCONFIG" ]] && break
    warn "файла $HOST_GITCONFIG нет. Создать его можно так: git config --global user.name \"Имя\""
  done
  write_env HOST_GITCONFIG "$HOST_GITCONFIG"
fi
pause "Enter, чтобы продолжить"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Рабочий репозиторий"
say "Папка, в которой opencode будет работать. Контейнер видит её на запись"
say "по тому же абсолютному пути, что и на хосте."
while true; do
  ask WORKSPACE "Путь к репозиторию:"
  WORKSPACE=$(expand_path "${WORKSPACE:-}")
  if [[ -n "$WORKSPACE" && -d "$WORKSPACE" ]]; then
    WORKSPACE=$(cd "$WORKSPACE" && pwd -P)
    break
  fi
  warn "папки '$WORKSPACE' нет"
done
write_env WORKSPACE "$WORKSPACE"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Пароль сервера"
say "Им браузер входит в веб-интерфейс (логин opencode)."
if [[ -n "$(_existing OPENCODE_SERVER_PASSWORD || true)" ]] && ! confirm "Пароль уже задан. Сменить?"; then
  say "оставил текущий пароль"
else
  if confirm "Сгенерировать случайный?"; then
    OPENCODE_SERVER_PASSWORD=$(generate_password)
  else
    OPENCODE_SERVER_PASSWORD=""
    while [[ ${#OPENCODE_SERVER_PASSWORD} -lt 12 ]]; do
      ask_secret OPENCODE_SERVER_PASSWORD "Пароль (от 12 символов):"
    done
  fi
  write_env OPENCODE_SERVER_PASSWORD "$OPENCODE_SERVER_PASSWORD"
fi
OPENCODE_SERVER_PASSWORD=$(_existing OPENCODE_SERVER_PASSWORD)

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Порт, часовой пояс, время обновления"
note "Enter без ввода берёт значение в квадратных скобках."
while true; do
  ask OPENCODE_PORT "Порт на хосте [$DEFAULT_PORT]:"
  OPENCODE_PORT="${OPENCODE_PORT:-$DEFAULT_PORT}"
  [[ "$OPENCODE_PORT" =~ ^[0-9]+$ ]] && (( OPENCODE_PORT >= 1 && OPENCODE_PORT <= 65535 )) && break
  warn "порт должен быть числом от 1 до 65535"
done
if command -v lsof >/dev/null 2>&1 && lsof -nP -iTCP:"$OPENCODE_PORT" -sTCP:LISTEN >/dev/null 2>&1; then
  warn "порт $OPENCODE_PORT уже кто-то слушает. Если это не этот же контейнер, выбери другой."
  if confirm "Ввести другой порт?"; then
    OPENCODE_PORT=""
    while ! [[ "$OPENCODE_PORT" =~ ^[0-9]+$ ]]; do
      ask OPENCODE_PORT "Порт на хосте:"
    done
  fi
fi
write_env OPENCODE_PORT "$OPENCODE_PORT"

detected_tz=$(host_timezone)
ask TZ "Часовой пояс [$detected_tz]:"
TZ="${TZ:-$detected_tz}"
write_env TZ "$TZ"

while true; do
  ask OPENCODE_UPDATE_HOUR "Час ежедневной проверки обновлений, 0-23 [$DEFAULT_UPDATE_HOUR]:"
  OPENCODE_UPDATE_HOUR="${OPENCODE_UPDATE_HOUR:-$DEFAULT_UPDATE_HOUR}"
  [[ "$OPENCODE_UPDATE_HOUR" =~ ^[0-9]+$ ]] && (( OPENCODE_UPDATE_HOUR <= 23 )) && break
  warn "нужно число от 0 до 23"
done
write_env OPENCODE_UPDATE_HOUR "$OPENCODE_UPDATE_HOUR"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Базовый образ и пакеты"
say "Образ собирается из $DEFAULT_BASE_IMAGE. Если Docker Hub недоступен или тормозит,"
say "можно взять Debian, который уже скачан локально."
local_debian=$(docker images debian --format '{{.Repository}}:{{.Tag}}' 2>/dev/null | grep -v ':<none>$' || true)
if docker image inspect "$DEFAULT_BASE_IMAGE" >/dev/null 2>&1; then
  say "✓ $DEFAULT_BASE_IMAGE уже есть локально"
  write_env BASE_IMAGE "$DEFAULT_BASE_IMAGE"
elif [[ -n "$local_debian" ]]; then
  say "Локально есть: $(printf '%s ' $local_debian)"
  local_choice=$(printf '%s\n' "$local_debian" | grep -m1 -- '-slim$' || printf '%s\n' "$local_debian" | head -n1)
  if confirm "Собирать из локального $local_choice?"; then
    write_env BASE_IMAGE "$local_choice"
  else
    write_env BASE_IMAGE "$DEFAULT_BASE_IMAGE"
  fi
else
  note "Локального Debian нет, $DEFAULT_BASE_IMAGE скачается при сборке."
  write_env BASE_IMAGE "$DEFAULT_BASE_IMAGE"
fi

printf '\n'
say "Тулчейн проекта ставится apt-пакетами в образ, например: build-essential python3-dev."
say "uv и Python агент может поставить сам, они лягут в ~/.local и переживут перезапуски."
while true; do
  ask EXTRA_APT_PACKAGES "Дополнительные apt-пакеты через пробел [$DEFAULT_APT_PACKAGES], «-» — без них:"
  EXTRA_APT_PACKAGES="${EXTRA_APT_PACKAGES:-$DEFAULT_APT_PACKAGES}"
  [[ "$EXTRA_APT_PACKAGES" == "-" ]] && EXTRA_APT_PACKAGES=""
  [[ "$EXTRA_APT_PACKAGES" =~ ^[a-z0-9.+:\ -]*$ ]] && break
  warn "имена apt-пакетов: строчные буквы, цифры и . + - :"
done
write_env EXTRA_APT_PACKAGES "$EXTRA_APT_PACKAGES"
pause "Enter, чтобы продолжить"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Владелец файлов"
if [[ "$(uname -s)" == "Linux" ]]; then
  say "На Linux контейнер должен работать под твоим UID и GID, иначе файлы в репозитории"
  say "будут принадлежать чужому пользователю."
  write_env OPENCODE_UID "$(id -u)"
  write_env OPENCODE_GID "$(id -g)"
else
  say "На macOS Docker сам сопоставляет владельца файлов, здесь настраивать нечего."
fi
pause "Enter, чтобы продолжить"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Дополнительные папки и симлинки"
say "Конфиги монтируются только на чтение. Абсолютные симлинки в них работают, только если"
say "их цель смонтирована по тому же пути. Соберу $OVERRIDE_FILE с нужными папками."
extra_mounts=()
scan_dirs=("$HOST_OPENCODE_CONFIG")
if [[ -d "$HOME/.agents" ]] && confirm "Подключить $HOME/.agents (глобальные скиллы)?"; then
  extra_mounts+=("$HOME/.agents:/home/opencode/.agents")
  scan_dirs+=("$HOME/.agents")
fi
if [[ -d "$HOME/.config/git" ]] && confirm "Подключить $HOME/.config/git (глобальный gitignore)?"; then
  extra_mounts+=("$HOME/.config/git:/home/opencode/.config/git")
fi
symlink_dirs=$(absolute_symlink_targets "${scan_dirs[@]}" | while IFS= read -r t; do mount_dir_for_target "$t"; printf '\n'; done | drop_nested_paths)
if [[ -n "$symlink_dirs" ]]; then
  say "Цели симлинков, которые смонтирую по тому же пути:"
  while IFS= read -r dir; do
    step "$dir"
    extra_mounts+=("$dir:$dir")
  done <<< "$symlink_dirs"
else
  say "Абсолютных симлинков не нашёл."
fi

if (( ${#extra_mounts[@]} == 0 )); then
  say "Дополнительных папок нет, $OVERRIDE_FILE не нужен."
elif [[ -f "$OVERRIDE_FILE" ]] && ! confirm "$OVERRIDE_FILE уже есть. Перезаписать?"; then
  SKIPPED+=("$OVERRIDE_FILE оставлен как был; проверь, что в нём есть нужные папки")
else
  {
    printf '# Generated by scripts/setup.sh. Per-machine read-only mounts.\n'
    printf 'services:\n  opencode:\n    volumes:\n'
    for mount in "${extra_mounts[@]}"; do
      printf '      - "%s:ro"\n' "$mount"
    done
  } > "$OVERRIDE_FILE"
  say "✓ записал $OVERRIDE_FILE"
fi
pause "Enter, чтобы продолжить"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Сервисы на хосте"
say "Внутри контейнера 127.0.0.1 и localhost означают сам контейнер. Если конфиг opencode"
say "ходит в локальный прокси или MCP-сервер на хосте, порт надо пробросить на хост."
found_ports=$(config_loopback_ports "$HOST_OPENCODE_CONFIG")
port_list=""
if [[ -n "$found_ports" ]]; then
  say "В конфиге нашёл локальные порты:"
  for port in ${found_ports//,/ }; do
    if command -v lsof >/dev/null 2>&1 && lsof -nP -iTCP:"$port" -sTCP:LISTEN >/dev/null 2>&1; then
      step "$port: на хосте его сейчас слушают"
    else
      step "$port: на хосте сейчас никто не слушает, запусти сервис до работы с opencode"
    fi
  done
  if confirm "Пробросить эти порты?"; then
    port_list="$found_ports"
  fi
else
  say "Локальных адресов в конфиге не нашёл."
fi
if [[ -z "$port_list" ]]; then
  while true; do
    ask HOST_LOOPBACK_PORTS "Порты через запятую (Enter — без проброса):"
    port_list="${HOST_LOOPBACK_PORTS:-}"
    port_list="${port_list// /}"
    [[ "$port_list" =~ ^([0-9]+(,[0-9]+)*)?$ ]] && break
    warn "нужен список чисел через запятую, например 17321,8080"
  done
fi
write_env HOST_LOOPBACK_PORTS "$port_list"
pause "Enter, чтобы продолжить"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Сборка и запуск"
server_url="http://localhost:$OPENCODE_PORT"
say "Соберу образ и подниму контейнер. При первом запуске он скачивает opencode с npm,"
say "это может занять несколько минут."
if ! confirm "Запускать?"; then
  SKIPPED+=("запуск: docker compose up -d --build")
else
  if ! docker compose up -d --build; then
    warn "сборка или запуск упали, вывод выше"
    SKIPPED+=("запуск: разберись с ошибкой и повтори docker compose up -d --build")
  elif ! wait_until_ready "$server_url/"; then
    warn "сервер не ответил за $((HEALTH_TIMEOUT_SECONDS / 60)) минут. Последние строки лога:"
    docker compose logs --tail 30 || true
    SKIPPED+=("запуск: смотри docker compose logs -f")
  else
    say "Логин в браузере: opencode"
    if printf '%s' "$OPENCODE_SERVER_PASSWORD" | copy_to_clipboard 2>/dev/null; then
      say "Пароль скопирован в буфер обмена."
    else
      say "Пароль лежит в .env, строка OPENCODE_SERVER_PASSWORD."
    fi
    open_url "$server_url"
    pause "Enter, когда вошёл"
  fi
fi

finish
say "Веб-интерфейс: $server_url  (логин opencode, пароль в .env)"
say "Ключи провайдеров хранятся в базе opencode, а не в конфиге. Если их нет в opencode.jsonc,"
say "подключи провайдера в веб-интерфейсе или так:"
say "  docker compose exec opencode opencode auth login --server http://127.0.0.1:4096"
say "Лог: docker compose logs -f    Остановить: docker compose down"
printf '\n'
}

run_wizard "$@"; exit
